mapper.select:
SELECT o.id, o.order_no, o.user_id, o.screening_id, o.movie_id, o.movie_title, o.cinema_id, o.status, o.total_amount, o.pay_expire_time, o.pay_time, o.cancel_type, o.create_time, u.phone AS user_phone, u.nickname AS user_nickname FROM t_order o LEFT JOIN t_user u ON u.id = o.user_id WHERE o.deleted = 0 AND u.deleted = 0
AND o.order_no = #{orderNo}
AND o.status = #{status}
AND o.cinema_id = #{cinemaId}
ORDER BY o.create_time DESC
